    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof importData>>, TError,ImportDataMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof importData>>, TError,ImportDataMutationVariables, TContext> => {

const mutationKey = getImportDataMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof importData>>, ImportDataMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  importData(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ImportDataMutationResult = NonNullable<Awaited<ReturnType<typeof importData>>>
    export type ImportDataMutationBody = BodyType<BackupInput>
    export type ImportDataMutationError = ErrorType<ErrorResponse>
    export type ImportDataMutationVariables = {data: BodyType<BackupInput>}

    /**
 * @summary Replace planner data from a backup
 */
